import {FORMA_LANGUAGES,currentLanguage,currentLocale,setLanguage,t,translateText,translateTree} from './i18n.js';
const modal=document.querySelector('#commerce-modal'),body=document.querySelector('#commerce-body');
const BILLING_KEY='forma-billing',ADS_KEY='fitness-copilot-ads';
const AD_POLICY={actionsPerInterstitial:5,cooldownMs:480000,dailyInterstitialLimit:2,bannerRoutes:[]};
let billing={plan:'yearly',...(JSON.parse(localStorage.getItem(BILLING_KEY)||'{}'))},paywallReason='manual',nativeAds=null,storeProducts={},productLoadFailed=false,interstitialPending=false;
const tr=source=>t(source),close=()=>modal.close(),saveBilling=()=>localStorage.setItem(BILLING_KEY,JSON.stringify(billing));
const isPro=()=>billing.status==='active'||(billing.status==='trial'&&new Date(billing.trialEnd).getTime()>Date.now());
function show(content){body.innerHTML=content;translateTree(body);if(!modal.open)modal.showModal();}
function notify(message){const toast=document.querySelector('#toast');if(toast){toast.textContent=tr(message);toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3500);}}
function productCopy(plan){const item=storeProducts[plan];if(!item)return{price:tr('Fiyat mağazada gösterilir'),trial:tr('Deneme uygunluğu mağazada doğrulanır')};const period=plan==='yearly'?tr('yıl'):tr('ay'),offer=item.intro;const units=Number(offer?.periodNumberOfUnits),unit=offer?.periodUnit;if(offer&&Number(offer.price)===0&&Number.isInteger(units)&&units>0&&['DAY','WEEK','MONTH','YEAR'].includes(unit)){const label=unit==='DAY'?'gün':unit==='WEEK'?'hafta':unit==='MONTH'?'ay':'yıl';return{price:`${item.price} / ${period}`,trial:translateText(`Uygunsan ${units} ${label} ücretsiz deneme; sonra ${item.price} / ${period}.`)};}return{price:`${item.price} / ${period}`,trial:tr('Ücretsiz deneme bu mağaza ürününde sunulmuyor')};}
function updateProductCopy(){for(const plan of ['yearly','monthly']){const copy=productCopy(plan),price=body.querySelector(`[data-store-price="${plan}"]`),offer=body.querySelector(`[data-store-offer="${plan}"]`);if(price)price.textContent=copy.price;if(offer)offer.textContent=copy.trial;}const chosen=productCopy(billing.plan),promise=body.querySelector('[data-trial-promise]'),cta=body.querySelector('[data-trial-cta]');if(promise)promise.textContent=chosen.trial;if(cta){cta.textContent=tr('Mağaza ödeme ekranına geç');cta.disabled=!!window.Capacitor?.isNativePlatform?.()&&(productLoadFailed||!storeProducts[billing.plan]);if(cta.disabled)cta.textContent=tr('Bu plan şu anda mağazada kullanılamıyor');}translateTree(body);}
function paywall(reason='manual'){
 paywallReason=reason;const atlas=reason==='atlas',onboarding=reason==='onboarding';
 show(`<div class="commerce-sheet pro-paywall"><div class="commerce-hero"><button class="commerce-close" data-commerce="dismiss-paywall" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot PRO · ${tr('Abonelik seçenekleri')}</span><h2>${tr(atlas?'Kas Atlası PRO ile açılır.':onboarding?'Planın hazır. Fitness Copilot PRO özelliklerini keşfet.':'Daha kişisel. Daha ölçülebilir.')}</h2><p>${tr(atlas?'467 anatomik yapıyı incele, kasa dokun ve o kası çalıştıran hareketleri bul.':'Akıllı planlama, Kas Atlası ve reklamsız antrenman deneyimini keşfet.')}</p><div class="trial-promise"><strong>${tr('Fiyat ve deneme koşulları')}</strong><span data-trial-promise>${tr('Deneme uygunluğu mağazada doğrulanır')}</span></div><div class="benefit-grid"><div class="benefit"><strong>◉ ${tr('Akıllı Koç')}</strong><small>${tr('RPE/RIR, hacim ve gelişim içgörüleri')}</small></div><div class="benefit"><strong>◈ Atlas Pro</strong><small>${tr('Kas ısı haritası ve gelişmiş anatomi')}</small></div><div class="benefit"><strong>∞ ${tr('Sınırsız plan')}</strong><small>${tr('Özel programlar ve ekipman profilleri')}</small></div><div class="benefit"><strong>⊘ ${tr('Reklamsız')}</strong><small>${tr('Kesintisiz keşif ve antrenman')}</small></div></div><div class="price-choice"><button class="price-card ${billing.plan==='yearly'?'selected':''}" data-commerce="plan" data-value="yearly"><span>${tr('Yıllık')}</span><b data-store-price="yearly">${tr('Fiyat mağazada gösterilir')}</b><small data-store-offer="yearly">${tr('Deneme uygunluğu mağazada doğrulanır')}</small></button><button class="price-card ${billing.plan==='monthly'?'selected':''}" data-commerce="plan" data-value="monthly"><span>${tr('Aylık')}</span><b data-store-price="monthly">${tr('Fiyat mağazada gösterilir')}</b><small data-store-offer="monthly">${tr('Deneme uygunluğu mağazada doğrulanır')}</small></button></div><button class="trial-button" data-commerce="trial" data-trial-cta>${tr('Aboneliği başlat')}</button><p class="billing-terms">${tr('Satın alma onayından önce mağaza, geçerli fiyatı ve varsa ücretsiz deneme süresini gösterir. Deneme sonrasında abonelik otomatik yenilenir ve iptal edilene kadar seçilen dönem için ücret alınır. İptal işlemi Apple veya Google hesap ayarlarından yapılır.')}</p><div class="billing-links"><a href="https://ali5921592-lang.github.io/gym1.2/privacy.html" data-commerce-link>${tr('Gizlilik Politikası')}</a><a href="https://ali5921592-lang.github.io/gym1.2/terms.html" data-commerce-link>${tr('Kullanım Koşulları')}</a><button data-commerce="manage">${tr('Üyeliği yönet')}</button><button data-commerce="privacy-options">${tr('Gizlilik ve reklam tercihleri')}</button><button data-commerce="restore">${tr('Satın almayı geri yükle')}</button></div></div>`);updateProductCopy();
}
function languages(){show(`<div class="commerce-sheet"><div class="commerce-hero"><button class="commerce-close" data-commerce="close" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot · GLOBAL</span><h2>${tr('Dilini seç')}</h2></div><div class="language-grid" data-i18n-ignore>${Object.entries(FORMA_LANGUAGES).map(([code,item])=>`<button class="language-option ${code===currentLanguage()?'active':''}" data-commerce="set-language" data-value="${code}"><strong>${item.native}</strong><small>${item.name}</small></button>`).join('')}</div></div>`)}
function membership(){const expiration=isPro()?(billing.trialEnd||billing.expiresAt):null,end=expiration?new Date(expiration):null;show(`<div class="commerce-sheet"><div class="commerce-hero"><button class="commerce-close" data-commerce="close" aria-label="Kapat">×</button><span class="commerce-kicker">Fitness Copilot PRO</span><h2>${tr('Üyeliği yönet')}</h2>${isPro()?`<div class="membership-card"><strong>${tr(billing.status==='trial'?'Denemen aktif':'Üyeliğin aktif')}</strong>${end?`<small>${end.toLocaleDateString(currentLocale())} ${tr(billing.status==='trial'?'tarihine kadar ücretsiz':'tarihine kadar geçerli')}</small>`:''}<p>${tr('Üyelik ve iptal işlemlerini mağaza hesabından yönetebilirsin.')}</p></div>`:`<p>${tr('Aktif üyelik veya deneme bulunmuyor.')}</p>`}<button class="secondary full" data-commerce="manage-store">${tr('Abonelik ayarlarını aç')}</button><button class="trial-button" data-commerce="close">${tr('Tamam')}</button></div></div>`)}
document.addEventListener('click',event=>{const link=event.target.closest('[data-commerce-link]');if(!link)return;event.preventDefault();const url=link.href;if(window.Capacitor?.isNativePlatform?.())window.dispatchEvent(new CustomEvent('fitness:open-link',{detail:{url}}));else window.open(url,'_blank','noopener');});
function adState(){const today=new Date().toISOString().slice(0,10),saved=JSON.parse(localStorage.getItem(ADS_KEY)||'{}');return saved.day===today?saved:{day:today,views:0,actions:0,last:0,onboardingShown:false};}
function saveAds(value){localStorage.setItem(ADS_KEY,JSON.stringify(value));}
function adSafe(){const appState=JSON.parse(localStorage.getItem('forma-v1')||'{}');return !isPro()&&!appState.activeSession&&!document.querySelector('#modal[open]')&&!modal.open;}
async function showInterstitial(source='navigation'){
 const ads=adState(),now=Date.now();if(interstitialPending||!adSafe()||ads.views>=AD_POLICY.dailyInterstitialLimit||ads.actions<AD_POLICY.actionsPerInterstitial||now-ads.last<AD_POLICY.cooldownMs)return false;
 interstitialPending=true;
 try{
  let shown=false;
  if(nativeAds?.showInterstitial){shown=await nativeAds.showInterstitial({placement:source})===true;}
  else if(!window.Capacitor?.isNativePlatform?.()){
   if(!adSafe())return false;
   show(`<div class="commerce-sheet interstitial-ad"><div class="ad-screen-label">${tr('REKLAM')}</div><div class="ad-creative"><span>FITNESS COPILOT PARTNER</span><h2>${tr('Antrenman ekipmanlarında üyeye özel fırsat')}</h2><p>${tr('Reklam, aktif antrenman sırasında gösterilmez.')}</p><button data-commerce="ad">${tr('Keşfet')}</button></div><button class="secondary full" data-commerce="close">${tr('Reklamı kapat')}</button></div>`);shown=true;
  }
  if(!shown)return false;
  const current=adState();current.views++;current.actions=0;current.last=Date.now();if(source==='onboarding')current.onboardingShown=true;saveAds(current);return true;
 }catch(error){console.error('Interstitial failed',error);return false;}
 finally{interstitialPending=false;}
}
function noteEligibleAction(source='navigation'){if(!adSafe())return;const ads=adState();ads.actions++;saveAds(ads);showInterstitial(source);}
function injectAd(){document.querySelector('.ad-slot')?.remove();}
new MutationObserver(()=>{clearTimeout(window.__fitnessAd);window.__fitnessAd=setTimeout(injectAd,120)}).observe(document.querySelector('#app'),{childList:true,subtree:true});
window.addEventListener('fitness:onboarding-complete',()=>setTimeout(()=>paywall('onboarding'),180));
window.addEventListener('fitness:eligible-action',event=>noteEligibleAction(event.detail?.source));
document.addEventListener('click',event=>{const button=event.target.closest('[data-commerce]');if(!button)return;const action=button.dataset.commerce;if(action==='paywall')paywall('manual');if(action==='language')languages();if(action==='close'||action==='dismiss-paywall')close();if(action==='plan'){billing.plan=button.dataset.value;paywall(paywallReason)}if(action==='set-language'&&setLanguage(button.dataset.value)){close();location.reload()}if(action==='trial'){if(window.Capacitor?.isNativePlatform?.()){close();window.dispatchEvent(new window.CustomEvent('forma:checkout',{detail:{product:billing.plan}}));}else notify('Abonelik satın alma işlemi iOS veya Android uygulamasında kullanılabilir.');}if(action==='privacy-options'){if(window.Capacitor?.isNativePlatform?.())window.dispatchEvent(new window.CustomEvent('fitness:privacy-options'));else notify('Reklam gizlilik ayarları mobil uygulamada açılır.');}if(action==='manage')membership();if(action==='manage-store'){if(window.Capacitor?.isNativePlatform?.())window.dispatchEvent(new CustomEvent('fitness:manage-subscriptions'));else notify('Abonelik ayarları cihazındaki App Store veya Google Play hesabında bulunur.');}if(action==='restore'){if(window.Capacitor?.isNativePlatform?.())window.dispatchEvent(new window.CustomEvent('fitness:restore-purchases'));else notify('Satın alımları geri yüklemek için iOS veya Android uygulamasını kullan.');}if(action==='ad')notify('Sponsor bağlantısı şu anda kullanılamıyor.');});
modal.addEventListener('click',event=>{if(event.target===modal&&!body.querySelector('[data-first-language],.pro-paywall'))close()});
window.addEventListener('fitness:products-ready',event=>{productLoadFailed=false;storeProducts=Object.fromEntries((event.detail?.products||[]).filter(item=>item.plan).map(item=>[item.plan,item]));updateProductCopy()});
window.addEventListener('fitness:products-error',()=>{productLoadFailed=true;storeProducts={};updateProductCopy()});
window.addEventListener('fitness:purchase-result',event=>{const result=event.detail||{};notify(result.ok?'Aboneliğin mağaza tarafından doğrulandı.':result.message||'Satın alma işlemi tamamlanamadı.')});
window.addEventListener('fitness:restore-result',event=>{const result=event.detail||{};notify(result.ok?'Satın alımlar mağaza hesabından kontrol edildi.':result.message||'Satın alımlar geri yüklenemedi.')});
window.addEventListener('fitness:privacy-options-result',event=>notify(event.detail?.available===false?'Bu bölgede ek reklam gizlilik seçeneği gerekmiyor.':'Reklam gizlilik seçenekleri şu anda açılamıyor.'));
window.FORMA_BILLING={getState:()=>({...billing}),getAdPolicy:()=>({...AD_POLICY,bannerRoutes:[...AD_POLICY.bannerRoutes]}),isPro,requestPro:paywall,noteEligibleAction,setAdAdapter:adapter=>{nativeAds=adapter;injectAd()},startCheckout:adapter=>adapter({product:billing.plan}),setEntitlement:(status,expiresAt)=>{billing={...billing,status,expiresAt,trialEnd:status==='trial'?expiresAt:null};saveBilling();window.dispatchEvent(new window.CustomEvent('fitness:entitlement-change'))}};
setTimeout(injectAd,300);
